func TestLv5_Parallel(t *testing.T) {
	j := runJob(t, jobOpts{workers: 4, nReduce: 3, seed: 13, limit: 8 * time.Second, needExit: true})
	for name, ws := range j.assigned {
		if len(ws) > 1 {
			fail(t, "dup_assign", say("没有任何故障，%s 却被分配了 %d 次。分出去的任务要立刻标记为进行中。", "There were no failures, yet %s was handed out %d times. Mark a task in progress as soon as you hand it out.", name, len(ws)))
		}
	}
	ws := map[int]bool{}
	for name, w := range j.assigned {
		if name[0] == 'M' {
			for _, x := range w {
				ws[x] = true
			}
		}
	}
	if len(ws) < 3 {
		fail(t, "no_parallel", say("4 个 worker、4 个 Map 任务，Map 只分给了 %d 个 worker。空闲的 worker 应该马上能领到任务。", "4 workers and 4 Map tasks, but Maps went to only %d workers. An idle worker should get a task right away.", len(ws)))
	}
}

